def Q(issue, number, topic, difficulty, form, tag, stem, choices, answer, explain, *quotes, passage=None):
    item = {"id": f"news26-{issue}-{number:02d}", "unit": 8, "type": "mc",
            "topic": topic, "difficulty": difficulty, "format": form, "tag": tag,
            "q": stem, "choices": choices, "answer": answer, "explain": explain,
            "quotes": [dict(r) for r in quotes]}
    if passage:
        item["passage"] = passage
    return item


